  },
  "devDependencies": {
    "@types/node": "^20.11.0",
    "@types/bun": "^1.1.0",
    "@biomejs/biome": "^1.8.0",
    "husky": "^9.1.7",
    "typescript": "^5.4.0"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "gray-matter": "^4.0.3",
    "js-yaml": "^4.1.1",
    "zod": "^4.4.3"
  }
}

/**
 * Frontmatter loader para arquivos de configuracao do usuario.
 *
 * Le o arquivo indicado e retorna o frontmatter YAML parseado junto com o
 * conteudo. Usado pelo parser de manifestos do plugin.
 */
import matter from 'gray-matter'
import { readFileSync } from 'fs'

export interface ParsedFrontmatter {
  data: Record<string, unknown>
  content: string
}

export function loadFrontmatter(filePath: string): ParsedFrontmatter {
  const raw = readFileSync(filePath, 'utf8')
  // Nenhuma sanitizacao aplicada antes do parse — arquivo vem do projeto do usuario.
  return matter(raw)
}
